            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Hi&#233;rophante-Mythique.html&quot; title=&quot;Le hi&#233;rophante mythique&quot;&gt;hi&#233;rophante&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Hi&#233;rophante-Mythique.html&quot; title=&quot;Aptitudes de voie du hi&#233;rophante mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Mar&#233;chal-Mythique.html&quot; title=&quot;Le mar&#233;chal mythique&quot;&gt;mar&#233;chal&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Mar&#233;chal-Mythique.html&quot; title=&quot;Aptitudes de voie du mar&#233;chal mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Protecteur-Mythique.html&quot; title=&quot;Le protecteur mythique&quot;&gt;protecteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Protecteur-Mythique.html&quot; title=&quot;Aptitudes de voie du protecteur mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-Voie-Universelles-Mythique.html&quot; title=&quot;Aptitudes de voie universelles Mythique&quot;&gt;Aptitudes de voie universelles&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Des-Enfants-Divins-Mythiques.html&quot; title=&quot;Aptitudes de voie des enfants divins mythiques&quot;&gt;Aptitudes de voie des enfants divins&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton3&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;3&#39;);&quot; onmouseout=&quot;outButton(&#39;3&#39;);&quot; onclick=&quot;expandMenu(&#39;3&#39;);&quot; /&gt;
&lt;/div&gt;Options de personnage mythiques&amp;emsp;
        &lt;ul ID=&quot;3&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-Mythiques.html&quot; title=&quot;Les dons mythiques&quot;&gt;Les dons mythiques&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Dons-Mythiques.html&quot; title=&quot;Dons mythiques&quot;&gt;tableau&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-L&#233;gendaires.html&quot; title=&quot;Objets l&#233;gendaires&quot;&gt;Les objets l&#233;gendaires&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-Magiques-Mythiques.html&quot; title=&quot;Les objets magiques mythiques&quot;&gt;Les objets magiques mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorts-Mythiques.html&quot; title=&quot;Les sorts mythiques&quot;&gt;Les sorts mythiques&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton4&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;4&#39;);&quot; onmouseout=&quot;outButton(&#39;4&#39;);&quot; onclick=&quot;expandMenu(&#39;4&#39;);&quot; /&gt;
&lt;/div&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Monstres-Mythiques.html&quot; title=&quot;Les monstres mythiques&quot;&gt;Les monstres mythiques&lt;/a&gt;&amp;emsp;
        &lt;ul ID=&quot;4&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;types-Simples-De-Cr&#233;atures-Mythiques.html&quot; title=&quot;Arch&#233;types simples de cr&#233;atures mythiques&quot;&gt;Arch&#233;types simples de cr&#233;atures mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Construire-Une-Cr&#233;ature-Mythique.html&quot; title=&quot;Construire une cr&#233;ature mythique&quot;&gt;Construire une cr&#233;ature mythique&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mythique.html&quot; title=&quot;Mythique (sous-type)&quot;&gt;Le sous-type mythique&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-De-Monstres-Mythiques-Universelles.html&quot; title=&quot;R&#232;gles de monstres mythiques universelles&quot;&gt;R&#232;gles de monstres mythiques universelles&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;valuer-Les-Statistiques-Des-Monstres.html&quot; title=&quot;&#201;valuer les statistiques des monstres&quot;&gt;&#201;valuer les statistiques des monstres&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Liste-Alphab&#233;tique-Des-Monstres-Mythiques.html&quot; title=&quot;Liste alphab&#233;tique des monstres mythiques&quot;&gt;Liste des monstres mythiques&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Campagnes mythiques (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Mythic Adventures, Mythic Origins/Campagnes mythiques&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoCMy.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Les arch&#233;types simples qui suivent peuvent servir &#224; transformer n’importe quel monstre en cr&#233;ature mythique. Une cr&#233;ature qui se voit attribuer l’un de ces arch&#233;types est consid&#233;r&#233;e comme une cr&#233;ature mythique en ce qui concerne les sorts, les pouvoirs et les objets magiques m&#234;me si elle n’a pas le &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mythique.html&quot; title=&quot;Mythique (sous-type)&quot;&gt;sous-type mythique&lt;/a&gt;. Notez que, comme elle ne poss&#232;de pas le sous-type mythique, elle ne profite pas des nombreux avantages qu’apporte ce sous-type : la cr&#233;ature ne profite que des avantages pr&#233;sent&#233;s dans l’arch&#233;type simple.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Agile (RMy 1, FP +1)&lt;a class=&quot;headeranchor&quot; id=&quot;Agile_RMy_B_FP_+B_0&quot; href=&quot;#Agile_RMy_B_FP_+B_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les cr&#233;atures ayant l’arch&#233;type agile sont rapides et redoutables, elles se d&#233;placent plus vite que leurs homologues normaux et frappent avec une vitesse et une agilit&#233; exceptionnelles. Les r&#232;gles abr&#233;g&#233;es des cr&#233;atures agiles sont les m&#234;mes que celles de reconstruction.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;R&#232;gles de reconstruction.&lt;/b&gt; ; &lt;b&gt;Init&lt;/b&gt; bonus +20 ; &lt;b&gt;CA&lt;/b&gt; bonus d’esquive +2 ; &lt;b&gt;pv&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Construire-Une-Cr&#233;ature-Mythique#Pointsdeviemythiquessupplementaires.html&quot; title=&quot;points de vie mythiques suppl&#233;mentaires&quot;&gt;points de vie mythiques suppl&#233;mentaires&lt;/a&gt; ; &lt;b&gt;Capacit&#233;s d&#233;fensives&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#ESQUIVETOTALE&quot; title=&quot;Le roublard&quot;&gt;esquive totale&lt;/a&gt; (comme le pouvoir de classe du &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html&quot; title=&quot;Le roublard&quot;&gt;roublard&lt;/a&gt;) ; &lt;b&gt;VD&lt;/b&gt; +9 m&#232;tres pour tous les types de d&#233;placement (jusqu’au double de la vitesse de d&#233;placement de base de la cr&#233;ature, au maximum) ; &lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Initiative-Double-(Capacit&#233;).html&quot; title=&quot;Initiative double (Ext) &amp;#91;Mythique&amp;#93;&quot;&gt;initiative double&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Profane (RMy 1 ou 2, FP +1)&lt;a class=&quot;headeranchor&quot; id=&quot;Profane_RMy_B_ou_C_FP_+B_1&quot; href=&quot;#Profane_RMy_B_ou_C_FP_+B_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les cr&#233;atures ayant l’arch&#233;type profane sont investies de pouvoir profane, elles sont capables de lancer un nombre limit&#233; de sorts profanes. Si la cr&#233;ature a 11 d&#233;s de vie ou plus, cet arch&#233;type simple lui accorde un &lt;a class=&quot;pagelink&quot; href=&quot;Rang-Mythique.html&quot; title=&quot;Rang mythique&quot;&gt;rang mythique&lt;/a&gt; de 2 au lieu de 1. Les r&#232;gles abr&#233;g&#233;es des cr&#233;atures profanes sont les m&#234;mes que celles de reconstruction.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;R&#232;gles de reconstruction.&lt;/b&gt; ; &lt;b&gt;CA&lt;/b&gt; bonus de parade +2 ; &lt;b&gt;pv&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Construire-Une-Cr&#233;ature-Mythique#Pointsdeviemythiquessupplementaires.html&quot; title=&quot;points de vie mythiques suppl&#233;mentaires&quot;&gt;points de vie mythiques suppl&#233;mentaires&lt;/a&gt; ; &lt;b&gt;RM&lt;/b&gt; elle gagne une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;RM&quot;&gt;RM&lt;/a&gt; &#233;gale &#224; son nouveau &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; + 11 ; &lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Incantation-Profane-Simple-(Capacit&#233;).html&quot; title=&quot;Incantation profane simple &amp;#91;Mythique&amp;#93;&quot;&gt;incantation profane simple&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Magie-Mythique-(Capacit&#233;).html&quot; title=&quot;Magie mythique (Sur) &amp;#91;Mythique&amp;#93;&quot;&gt;magie mythique&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Divin (RMy 1 ou 2, FP +1)&lt;a class=&quot;headeranchor&quot; id=&quot;Divin_RMy_B_ou_C_FP_+B_2&quot; href=&quot;#Divin_RMy_B_ou_C_FP_+B_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les cr&#233;atures ayant l’arch&#233;type divin peuvent invoquer le pouvoir des dieux, ce qui leur permet de lancer un nombre limit&#233; de sorts divins. Si la cr&#233;ature a 11 d&#233;s de vie ou plus, cet arch&#233;type simple lui accorde un &lt;a class=&quot;pagelink&quot; href=&quot;Rang-Mythique.html&quot; title=&quot;Rang mythique&quot;&gt;rang mythique&lt;/a&gt; de 2 au lieu de 1. Les r&#232;gles abr&#233;g&#233;es des cr&#233;atures divines sont les m&#234;mes que celles de reconstruction.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;R&#232;gles de reconstruction.&lt;/b&gt; ; &lt;b&gt;Aura&lt;/b&gt; aura de gr&#226;ce (la cr&#233;ature et tous ses alli&#233;s dans un rayon de 9 m&#232;tres re&#231;oivent un bonus de saintet&#233; de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; ou un bonus de malfaisance si la cr&#233;ature poss&#233;dant l’arch&#233;type est Mauvaise) ; &lt;b&gt;CA&lt;/b&gt; bonus de parade +2 ; &lt;b&gt;pv&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Construire-Une-Cr&#233;ature-Mythique#Pointsdeviemythiquessupplementaires.html&quot; title=&quot;points de vie mythiques suppl&#233;mentaires&quot;&gt;points de vie mythiques suppl&#233;mentaires&lt;/a&gt; ; &lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Incantation-Divine-Simple-(Capacit&#233;).html&quot; title=&quot;Incantation divine simple &amp;#91;Mythique&amp;#93;&quot;&gt;incantation divine simple&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Magie-Mythique-(Capacit&#233;).html&quot; title=&quot;Magie mythique (Sur) &amp;#91;Mythique&amp;#93;&quot;&gt;magie mythique&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Invincible (RMy 1 ou 2, FP +1)&lt;a class=&quot;headeranchor&quot; id=&quot;Invincible_RMy_B_ou_C_FP_+B_3&quot; href=&quot;#Invincible_RMy_B_ou_C_FP_+B_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 16px 16px&quot;&gt;
&lt;div style=&quot;border: 1px solid #4b3124; padding: 4px&quot;&gt;
&lt;table CLASS=&quot;tablo centre autoalt&quot;&gt;&lt;caption&gt;D&#233;fenses de l’arch&#233;type invincible&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;DV&lt;/td&gt;&lt;td&gt;R&#233;sistances aux &#233;nergies&lt;br /&gt;destructives&lt;/td&gt;&lt;td&gt;RD&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;1-4&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;5-10&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;td&gt;5/&#233;pique&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;11+&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;td&gt;10/&#233;pique&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;/div&gt;Les cr&#233;atures ayant l’arch&#233;type invincible sont extr&#234;mement difficiles &#224; blesser. Elles peuvent supporter des ch&#226;timents exceptionnels et poursuivre le combat. Si la cr&#233;ature a 11 d&#233;s de vie ou plus, cet arch&#233;type simple lui accorde un &lt;a class=&quot;pagelink&quot; href=&quot;Rang-Mythique.html&quot; title=&quot;Rang mythique&quot;&gt;rang mythique&lt;/a&gt; de 2 au lieu de 1. Les r&#232;gles abr&#233;g&#233;es des cr&#233;atures invincibles sont les m&#234;mes que celles de reconstruction.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;R&#232;gles de reconstruction.&lt;/b&gt; ; &lt;b&gt;CA&lt;/b&gt; augmentation du bonus d’armure naturelle de 2 (ou de 4 si la cr&#233;ature a 11 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;d&#233;s de vie&lt;/a&gt; ou plus) ; &lt;b&gt;pv&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Construire-Une-Cr&#233;ature-Mythique#Pointsdeviemythiquessupplementaires.html&quot; title=&quot;points de vie mythiques suppl&#233;mentaires&quot;&gt;points de vie mythiques suppl&#233;mentaires&lt;/a&gt; ; &lt;b&gt;Capacit&#233;s d&#233;fensives&lt;/b&gt; elle gagne une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; et une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance (aux &#233;nergies destructrices) (Ext)&quot;&gt;r&#233;sistance&lt;/a&gt; &#224; tous les types d’&#233;nergie comme indiqu&#233; dans la table ci-contre, ainsi que &lt;a class=&quot;pagelink&quot; href=&quot;Blocage-Des-Attaques-(Capacit&#233;).html&quot; title=&quot;Blocage des attaques (Ext)&quot;&gt;blocage des attaques&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Second-Jet-De-Sauvegarde-(Capacit&#233;).html&quot; title=&quot;Second jet de sauvegarde (Ext) &amp;#91;Mythique&amp;#93;&quot;&gt;second jet de sauvegarde&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Sauvage (RMy 1 ou 2, FP +1)&lt;a class=&quot;headeranchor&quot; id=&quot;Sauvage_RMy_B_ou_C_FP_+B_4&quot; href=&quot;#Sauvage_RMy_B_ou_C_FP_+B_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 16px 16px&quot;&gt;
&lt;div style=&quot;border: 1px solid #4b3124; padding: 4px&quot;&gt;
&lt;table CLASS=&quot;tablo centre autoalt&quot;&gt;&lt;caption&gt;D&#233;fenses de l’arch&#233;type sauvage&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;DV&lt;/td&gt;&lt;td&gt;R&#233;sistances aux &#233;nergies&lt;br /&gt;destructives&lt;/td&gt;&lt;td&gt;RD&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;1-4&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;5-10&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;td&gt;5/&#233;pique&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;11+&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;td&gt;10/&#233;pique&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;/div&gt;Les cr&#233;atures ayant l’arch&#233;type sauvage sont indompt&#233;es, ce sont des versions primitives de leurs cousines &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Nonmythique.html&quot; title=&quot;non-mythiques&quot;&gt;non-mythiques&lt;/a&gt;. Elles ont des griffes plus ac&#233;r&#233;es, des crocs plus longs et une peau plus &#233;paisse. Si la cr&#233;ature a 11 d&#233;s de vie ou plus, cet arch&#233;type simple lui accorde un &lt;a class=&quot;pagelink&quot; href=&quot;Rang-Mythique.html&quot; title=&quot;Rang mythique&quot;&gt;rang mythique&lt;/a&gt; de 2 au lieu de 1. Les r&#232;gles abr&#233;g&#233;es des cr&#233;atures sauvages sont les m&#234;mes que celles de reconstruction.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;R&#232;gles de reconstruction.&lt;/b&gt; ; &lt;b&gt;CA&lt;/b&gt; augmentation du bonus d’armure naturelle de 2 ; &lt;b&gt;pv&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Construire-Une-Cr&#233;ature-Mythique#Pointsdeviemythiquessupplementaires.html&quot; title=&quot;points de vie mythiques suppl&#233;mentaires&quot;&gt;points de vie mythiques suppl&#233;mentaires&lt;/a&gt; ; &lt;b&gt;Capacit&#233;s d&#233;fensives&lt;/b&gt; elle gagne une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; et une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance (aux &#233;nergies destructrices) (Ext)&quot;&gt;r&#233;sistance&lt;/a&gt; &#224; tous les types d’&#233;nergie comme indiqu&#233; dans la table ci-contre ; &lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; toutes les attaques gagnent &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Saignement.html&quot; title=&quot;Saignement&quot;&gt;saignement&lt;/a&gt; 1 (qui se cumule avec lui-m&#234;me) et &lt;a class=&quot;pagelink&quot; href=&quot;Sauvagerie-F&#233;roce-(Capacit&#233;).html&quot; title=&quot;Sauvagerie f&#233;roce (Sur) &amp;#91;Mythique&amp;#93;&quot;&gt;sauvagerie f&#233;roce&lt;/a&gt; (attaque &#224; outrance).
